def isCircle(N, A):
    if N == 0:
        return 0

    # Create a graph where each character is a node and there is an edge from
    # character u to character v if a string ends with u and starts with v.
    graph = {}
    in_degree = {}
    out_degree = {}

    for s in A:
        u = s[0]
        v = s[-1]
        if u not in graph:
            graph[u] = []
        graph[u].append(v)
        out_degree[u] = out_degree.get(u, 0) + 1
        in_degree[v] = in_degree.get(v, 0) + 1

    # Check if the graph has an eulerian circuit (all vertices with non-zero degree
    # are in the same strongly connected component and each vertex with non-zero degree
    # has the same in-degree as out-degree).
    start_nodes = 0
    end_nodes = 0
    for u in graph:
        if out_degree[u] != in_degree.get(u, 0):
            if out_degree[u] == in_degree.get(u, 0) + 1:
                end_nodes += 1
            elif out_degree[u] + 1 == in_degree.get(u, 0):
                start_nodes += 1
            else:
                return 0

    if not (start_nodes == 0 and end_nodes == 0 or start_nodes == 1 and end_nodes == 1):
        return 0

    # Check if the graph is strongly connected.
    visited = set()
    stack = []

    def dfs(node):
        visited.add(node)
        if node in graph:
            for neighbor in graph[node]:
                if neighbor not in visited:
                    dfs(neighbor)
        stack.append(node)

    # Find a node with non-zero degree to start DFS.
    for u in graph:
        if out_degree[u] > 0:
            dfs(u)
            break

    # If DFS does not visit all nodes, the graph is not strongly connected.
    if len(visited) != len(graph):
        return 0

    return 1

